-- Add searchable employee ID references beside the existing numeric user keys.
ALTER TABLE ERM_USERS ADD COLUMN IF NOT EXISTS REPORTING_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_USER_ROLES ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_USER_BANK_DETAILS ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_EMPLOYEE_DESIGNATION_REQUESTS
    ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS REQUESTED_REPORTING_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_EMPLOYEE_PROFILE_UPDATE_REQUESTS
    ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS CURRENT_REPORTING_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS REQUESTED_REPORTING_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS REPLACEMENT_TEAM_LEAD_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_LEAVE_REQUESTS
    ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS APPROVER_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_PROJECT_REQUESTS
    ADD COLUMN IF NOT EXISTS DELIVERY_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS PROJECT_OWNER_EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS PROJECT_DIRECTOR_EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS PROJECT_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_PROJECT_CHANGE_REQUESTS
    ADD COLUMN IF NOT EXISTS DELIVERY_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS PROJECT_OWNER_EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS PROJECT_DIRECTOR_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_PROJECT_ALLOCATIONS ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_SUPPORT_QUEUE_MEMBERS ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_SUPPORT_TICKETS
    ADD COLUMN IF NOT EXISTS REQUESTER_EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS ASSIGNEE_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_ONBOARDING_REQUESTS ADD COLUMN IF NOT EXISTS REPORTING_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_ATTENDANCE_TIMESHEETS
    ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL,
    ADD COLUMN IF NOT EXISTS APPROVER_MANAGER_EMPLOYEE_ID VARCHAR(50) NULL;
ALTER TABLE ERM_ATTENDANCE_LEAVE_RECONCILIATIONS ADD COLUMN IF NOT EXISTS EMPLOYEE_ID VARCHAR(50) NULL;

-- Backfill every reference using the existing numeric foreign key.
UPDATE ERM_USERS child JOIN ERM_USERS parent ON parent.ID = child.REPORTING_MANAGER_USER_ID
SET child.REPORTING_MANAGER_EMPLOYEE_ID = parent.EMPLOYEE_ID;
UPDATE ERM_USER_ROLES link JOIN ERM_USERS u ON u.ID = link.USER_ID SET link.EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_USER_BANK_DETAILS link JOIN ERM_USERS u ON u.ID = link.USER_ID SET link.EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_EMPLOYEE_DESIGNATION_REQUESTS x JOIN ERM_USERS u ON u.ID = x.EMPLOYEE_USER_ID SET x.EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_EMPLOYEE_DESIGNATION_REQUESTS x JOIN ERM_USERS u ON u.ID = x.REQUESTED_REPORTING_MANAGER_USER_ID SET x.REQUESTED_REPORTING_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_EMPLOYEE_PROFILE_UPDATE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.EMPLOYEE_USER_ID SET x.EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_EMPLOYEE_PROFILE_UPDATE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.CURRENT_REPORTING_MANAGER_USER_ID SET x.CURRENT_REPORTING_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_EMPLOYEE_PROFILE_UPDATE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.REQUESTED_REPORTING_MANAGER_USER_ID SET x.REQUESTED_REPORTING_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_EMPLOYEE_PROFILE_UPDATE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.REPLACEMENT_TEAM_LEAD_USER_ID SET x.REPLACEMENT_TEAM_LEAD_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_LEAVE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.EMPLOYEE_USER_ID SET x.EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_LEAVE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.APPROVER_MANAGER_USER_ID SET x.APPROVER_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_PROJECT_REQUESTS x JOIN ERM_USERS u ON u.ID = x.DELIVERY_MANAGER_USER_ID SET x.DELIVERY_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_PROJECT_REQUESTS x JOIN ERM_USERS u ON u.ID = x.PROJECT_OWNER_USER_ID SET x.PROJECT_OWNER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_PROJECT_REQUESTS x JOIN ERM_USERS u ON u.ID = x.PROJECT_DIRECTOR_USER_ID SET x.PROJECT_DIRECTOR_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_PROJECT_REQUESTS x JOIN ERM_USERS u ON u.ID = x.PROJECT_MANAGER_USER_ID SET x.PROJECT_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_PROJECT_CHANGE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.DELIVERY_MANAGER_USER_ID SET x.DELIVERY_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_PROJECT_CHANGE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.PROJECT_OWNER_USER_ID SET x.PROJECT_OWNER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_PROJECT_CHANGE_REQUESTS x JOIN ERM_USERS u ON u.ID = x.PROJECT_DIRECTOR_USER_ID SET x.PROJECT_DIRECTOR_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_PROJECT_ALLOCATIONS x JOIN ERM_USERS u ON u.ID = x.EMPLOYEE_USER_ID SET x.EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_SUPPORT_QUEUE_MEMBERS x JOIN ERM_USERS u ON u.ID = x.USER_ID SET x.EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_SUPPORT_TICKETS x JOIN ERM_USERS u ON u.ID = x.REQUESTER_USER_ID SET x.REQUESTER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_SUPPORT_TICKETS x JOIN ERM_USERS u ON u.ID = x.ASSIGNEE_USER_ID SET x.ASSIGNEE_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_ONBOARDING_REQUESTS x JOIN ERM_USERS u ON u.ID = x.REPORTING_MANAGER_USER_ID SET x.REPORTING_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_ATTENDANCE_TIMESHEETS x JOIN ERM_USERS u ON u.ID = x.EMPLOYEE_USER_ID SET x.EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_ATTENDANCE_TIMESHEETS x JOIN ERM_USERS u ON u.ID = x.APPROVER_MANAGER_USER_ID SET x.APPROVER_MANAGER_EMPLOYEE_ID = u.EMPLOYEE_ID;
UPDATE ERM_ATTENDANCE_LEAVE_RECONCILIATIONS x JOIN ERM_USERS u ON u.ID = x.EMPLOYEE_USER_ID SET x.EMPLOYEE_ID = u.EMPLOYEE_ID;

-- Preserve required-reference guarantees for required user relationships.
ALTER TABLE ERM_USER_ROLES MODIFY COLUMN EMPLOYEE_ID VARCHAR(50) NOT NULL;
ALTER TABLE ERM_USER_BANK_DETAILS MODIFY COLUMN EMPLOYEE_ID VARCHAR(50) NOT NULL;
