ALTER TABLE ERM_EMPLOYEE_PROFILE_UPDATE_REQUESTS MODIFY COLUMN REQUESTED_REPORTING_MANAGER_EMPLOYEE_ID VARCHAR(50) NOT NULL;
ALTER TABLE ERM_LEAVE_REQUESTS MODIFY COLUMN EMPLOYEE_ID VARCHAR(50) NOT NULL;
ALTER TABLE ERM_PROJECT_REQUESTS MODIFY COLUMN DELIVERY_MANAGER_EMPLOYEE_ID VARCHAR(50) NOT NULL;
