-- Employee IDs are unique alternate keys on ERM_USERS and are enforced as real foreign keys.
ALTER TABLE ERM_USERS ADD CONSTRAINT FK_USERS_MANAGER_EMPLOYEE FOREIGN KEY (REPORTING_MANAGER_EMPLOYEE_ID) REFERENCES ERM_USERS (EMPLOYEE_ID) ON UPDATE CASCADE;
